//! `service::convert_ypt` against the REAL CodeWalker bridge (`tools/ypt-bridge`).
//!
//! Skips (loudly) when `dotnet` or the built bridge is not available, so a plain `cargo test`
//! works everywhere. Fixtures were generated by the TypeScript exporter
//! (`VFXFORGE_GEN_NATIVE_FIXTURES=1 npx vitest run packages/export/test/gen-native-fixtures.test.ts`).

use std::path::PathBuf;
use vfxforge_native::bridge::{bridge_status, BridgeConfig};
use vfxforge_native::jobs::CancelToken;
use vfxforge_native::service::{convert_ypt, ConvertArgs};
use vfxforge_native::Error;

fn bridge_cfg() -> Option<BridgeConfig> {
    let dll = std::env::var_os("VFXFORGE_BRIDGE_DLL")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tools/ypt-bridge/out/vfxforge-ypt-bridge.dll"));
    if !dll.is_file() {
        eprintln!("SKIPPED: bridge not built at {}", dll.display());
        return None;
    }
    let cfg = BridgeConfig { dotnet: None, dll: Some(dll) };
    let st = bridge_status(&cfg);
    if !st.available {
        eprintln!("SKIPPED: bridge not usable: {}", st.detail);
        return None;
    }
    Some(cfg)
}

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures").join(name)).expect("fixture")
}

fn args(gen9: bool) -> ConvertArgs {
    ConvertArgs {
        xml: String::from_utf8(fixture("tiny_fx.ypt.xml")).unwrap(),
        gen9,
        asset_name: "tiny_fx".into(),
        files: vec![("tinyfx.dds".into(), fixture("tinyfx.dds"))],
    }
}

#[test]
fn converts_and_verifies_a_legacy_ypt() {
    let Some(cfg) = bridge_cfg() else { return };
    let scratch = tempfile::tempdir().unwrap();
    let (meta, ypt) = convert_ypt(&cfg, scratch.path(), &args(false), &CancelToken::new()).expect("conversion");
    assert!(meta.round_trip_ok, "CodeWalker could not read its own output back: {:?}", meta.mismatches);
    assert!(meta.mismatches.is_empty());
    assert_eq!(&ypt[..4], b"RSC7", "binary must be an RSC7 resource");
    assert!(ypt.len() > 1000);
    assert!(meta.codewalker_core.is_some());
    assert_eq!(std::fs::read_dir(scratch.path()).unwrap().count(), 0, "scratch must be cleaned up");
}

#[test]
fn gen9_target_produces_a_different_resource_version() {
    let Some(cfg) = bridge_cfg() else { return };
    let scratch = tempfile::tempdir().unwrap();
    let (legacy, _) = convert_ypt(&cfg, scratch.path(), &args(false), &CancelToken::new()).unwrap();
    let (gen9, ypt9) = convert_ypt(&cfg, scratch.path(), &args(true), &CancelToken::new()).unwrap();
    assert!(gen9.round_trip_ok, "{:?}", gen9.mismatches);
    assert_ne!(legacy.resource_version, gen9.resource_version);
    assert_eq!(&ypt9[..4], b"RSC7");
}

#[test]
fn a_missing_texture_is_reported_not_papered_over() {
    let Some(cfg) = bridge_cfg() else { return };
    let scratch = tempfile::tempdir().unwrap();
    let mut a = args(false);
    a.files.clear();
    match convert_ypt(&cfg, scratch.path(), &a, &CancelToken::new()) {
        Err(Error::ToolFailed { detail, .. }) => assert!(detail.to_lowercase().contains("texture") || detail.contains("missing"), "{detail}"),
        other => panic!("expected the bridge to refuse a project with a missing texture, got {other:?}"),
    }
}

#[test]
fn cancellation_stops_the_conversion() {
    let Some(cfg) = bridge_cfg() else { return };
    let scratch = tempfile::tempdir().unwrap();
    let cancel = CancelToken::new();
    cancel.cancel();
    assert!(matches!(convert_ypt(&cfg, scratch.path(), &args(false), &cancel), Err(Error::Cancelled)));
}
